<?php
require_once __DIR__ . '/../includes/auth.php';$u=require_role(['user']);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$img=upload_item_image();$stmt=$pdo->prepare("INSERT INTO lost_items(item_name,category,description,color,date_lost,quantity,has_items_inside,image_path,status,location_last_seen,posted_by) VALUES(?,?,?,?,?,?,?,?, 'Lost',?,?)");$stmt->execute([trim($_POST['item_name']),trim($_POST['category']),trim($_POST['description']??''),trim($_POST['color']??''),$_POST['date_lost']?:null,max(1,(int)$_POST['quantity']),isset($_POST['has_items_inside'])?1:0,$img,trim($_POST['location_last_seen']??''),$u['id']]);$id=(int)$pdo->lastInsertId();$h=$pdo->prepare("INSERT INTO item_history(item_id,changed_by,new_status,action_description) VALUES(?,?, 'Lost','New missing-item post created')");$h->execute([$id,$u['id']]);redirect('my-items.php?created=1');}catch(Throwable $e){$error=$e->getMessage();}}
page_header('Post Missing Item');?><h1>Post a Missing Item</h1><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?>
<div class="panel"><div class="panel-body"><form method="post" enctype="multipart/form-data"><?=csrf_field()?><div class="form-grid">
<div class="field"><label>Item Name *</label><input name="item_name" required maxlength="150"></div><div class="field"><label>Category *</label><select name="category" required><option value="">Select category</option><?php foreach(['ID/Card','Electronics','Wallet/Purse','Bag','Clothing','Books/School Supplies','Keys','Accessories','Others'] as $c):?><option><?=e($c)?></option><?php endforeach;?></select></div>
<div class="field"><label>Color</label><input name="color"></div><div class="field"><label>Date Lost</label><input type="date" name="date_lost"></div><div class="field"><label>Quantity</label><input type="number" name="quantity" min="1" value="1" required></div><div class="field"><label>Location Last Seen</label><input name="location_last_seen"></div>
<div class="field wide"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Item Picture (max 3 MB)</label><input type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp"></div><div class="field"><label><input style="width:auto" type="checkbox" name="has_items_inside"> Has items inside?</label></div>
</div><button>Submit Missing Item</button></form></div></div><?php page_footer();?>
